func detect(conn net.Conn, enableProxyProtocol bool) (*Conn, error) {
	reader := bufio.NewReader(conn)

	// the first attempt is to parse optional proxy
	// protocol line that is injected by load balancers
	// before actual protocol traffic flows.
	// if the first attempt encounters proxy it
	// goes to the second pass to do protocol detection
	var proxyLine *ProxyLine
	for i := 0; i < 2; i++ {
		proto, err := detectProto(reader)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		var clientAddr net.Addr
		if proto == ProtoSSH {
			// A Teleport client may send metadata before its SSH version. Read
			// the complete header so it can be parsed even if it arrived in
			// multiple packets, then replay it for the SSH server, which also
			// uses the metadata for tracing.
			in, _ := reader.Peek(8) // detectProto already peeked these bytes.
			if bytes.Equal(in, []byte(sshutils.ProxyHelloSignature)[:8]) {
				var payload sshutils.HandshakePayload
				var header []byte
				header, err = reader.ReadSlice(0)
				if err != nil {
					return nil, trace.Wrap(err, "failed to read Teleport proxy header")
				}
				if err := json.Unmarshal(header[len(sshutils.ProxyHelloSignature):len(header)-1], &payload); err != nil {
					return nil, trace.Wrap(err, "failed to parse Teleport proxy header")
				}
				if payload.ClientAddr != "" {
					if addr, err := utils.ParseAddr(payload.ClientAddr); err == nil {
						clientAddr = addr
						if addr.AddrNetwork == "tcp" {
							if ip := net.ParseIP(addr.Host()); ip != nil {
								clientAddr = &net.TCPAddr{IP: ip, Port: addr.Port(0)}
							}
						}
					}
				}
				reader = bufio.NewReader(io.MultiReader(bytes.NewReader(append([]byte(nil), header...)), reader))
			}
		}

		switch proto {
		case ProtoProxy:
			if !enableProxyProtocol {
				return nil, trace.BadParameter("proxy protocol support is disabled")
			}
			if proxyLine != nil {
				return nil, trace.BadParameter("duplicate proxy line")
			}
			proxyLine, err = ReadProxyLine(reader)
			if err != nil {
				return nil, trace.Wrap(err)
			}
		case ProtoProxyV2:
			if !enableProxyProtocol {
				return nil, trace.BadParameter("proxy protocol support is disabled")
			}
			if proxyLine != nil {
				return nil, trace.BadParameter("duplicate proxy line")
			}
			proxyLine, err = ReadProxyLineV2(reader)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			// repeat the cycle to detect the protocol
		case ProtoTLS, ProtoSSH, ProtoHTTP:
			return &Conn{
				protocol:  proto,
				Conn:      conn,
				reader:    reader,
				proxyLine: proxyLine,
				clientAddr: clientAddr,
			}, nil
		case ProtoPostgres:
			return &Conn{
				protocol: proto,
				Conn:     conn,
				reader:   reader,
			}, nil
		}
	}

	ProtoUnknown Protocol = iota
	// ProtoTLS is TLS protocol
	ProtoTLS
	// ProtoSSH is SSH protocol
	ProtoSSH
	// ProtoProxy is a HAProxy proxy line protocol
	ProtoProxy
	// ProtoProxyV2 is a HAProxy binary protocol
	ProtoProxyV2
	// ProtoHTTP is HTTP protocol
	ProtoHTTP
	// ProtoPostgres is PostgreSQL wire protocol
	ProtoPostgres
)

// protocolStrings defines strings for each Protocol.
var protocolStrings = map[Protocol]string{
	ProtoUnknown:  "Unknown",
	ProtoTLS:      "TLS",
	ProtoSSH:      "SSH",
	ProtoProxy:    "Proxy",
	ProtoProxyV2:  "ProxyV2",
	ProtoHTTP:     "HTTP",
	ProtoPostgres: "Postgres",
}

// String returns the string representation of Protocol p.
// An empty string is returned when the protocol is not defined.
func (p Protocol) String() string {
	return protocolStrings[p]
}

