// Read implements io.Read() part of net.Connection which allows us
// peek at the beginning of SSH handshake (that's why we're wrapping the connection)
func (c *connectionWrapper) Read(b []byte) (int, error) {
	// handshake already took place, forward upstream:
	if c.upstreamReader != nil {
		return c.upstreamReader.Read(b)
	}
	if len(b) == 0 {
		return 0, nil
	}

	reader := bufio.NewReader(c.Conn)
	signature := []byte(sshutils.ProxyHelloSignature)
	// Check the signature one byte at a time so an ordinary SSH client does
	// not have to send a full proxy header before its first read completes.
	for i, want := range signature {
		prefix, err := reader.Peek(i + 1)
		if err != nil || prefix[i] != want {
			c.upstreamReader = reader
			return reader.Read(b)
		}
	}

	// The signature matched. Read the entire payload even when the network
	// splits it across reads, while retaining any subsequent SSH bytes.
	if _, err := reader.Discard(len(signature)); err != nil {
		return 0, trace.Wrap(err)
	}
	payload := make([]byte, 0, MaxVersionStringBytes)
	for {
		char, err := reader.ReadByte()
		if err != nil {
			return 0, trace.Wrap(err, "failed to read Teleport proxy payload")
		}
		if char == 0 {
			break
		}
		if len(payload) == maxProxyHandshakePayloadBytes {
			return 0, trace.BadParameter("Teleport proxy payload exceeds %d bytes", maxProxyHandshakePayloadBytes)
		}
		payload = append(payload, char)
	}

	var hp sshutils.HandshakePayload
	if err := json.Unmarshal(payload, &hp); err != nil {
		c.logger.Error(err)
	} else {
		if ca, err := utils.ParseAddr(hp.ClientAddr); err == nil {
			// Source-address checks in the SSH server require a TCPAddr.
			c.clientAddr = ca
			if ca.AddrNetwork == "tcp" {
				if ip := net.ParseIP(ca.Host()); ip != nil {
					c.clientAddr = &net.TCPAddr{IP: ip, Port: ca.Port(0)}
				}
			}
		}
		c.traceContext = hp.TracingContext
	}
	c.upstreamReader = reader
	return reader.Read(b)
}

